// The pattern's bodies, as include/blz/cuda_kernels.cuh expects them.
struct lcyc_kernels {
  template <class Sink>
  __device__ static void trigger(const GraphView& g, const Params& p, std::uint32_t e, Sink& out) {
    lcyc_trigger(g, p, e, out);
  }
  template <class Sink>
  __device__ static void warp(const GraphView& g, const Params& p, std::uint32_t e, std::uint32_t lane, Sink& out) {
    lcyc_trigger_warp(g, p, e, lane, out);
  }
  __device__ static std::uint32_t work(const GraphView& g, const Params& p, std::uint32_t e) {
    return lcyc_work(g, p, e);
  }
};

void lcyc_cuda_bucket(const GraphView& g, const Params& p, std::uint64_t first, std::uint32_t count, std::uint32_t threshold, std::uint8_t* flags, void* stream) {
  cuda::launch_bucket<lcyc_kernels>(g, p, first, count, threshold, flags, stream);
}

void lcyc_cuda(const GraphView& g, const Params& p, const CudaRun& run) {
  cuda::launch<lcyc_kernels>(g, p, run);
}

